<script setup lang="ts">
import { computed } from 'vue'
type Row = Record<string, any>
const api = usePublicApi()
const filters = useFilterState()
const kind = computed({ get: () => String(filters.get('kind') || 'ocds'), set: (v: string) => void filters.setAll({ kind: v, ocid: undefined, document_id: undefined, a: undefined, b: undefined }) })
const ocid = computed(() => String(filters.get('ocid') || ''))
const documentId = computed(() => String(filters.get('document_id') || ''))
const a = computed(() => String(filters.get('a') || ''))
const b = computed(() => String(filters.get('b') || ''))
const target = computed(() => kind.value === 'ocds' ? ocid.value || (a.value && b.value) : documentId.value || (a.value && b.value))
const { data, pending, error } = await useAsyncData<Row | null>(() => `public-record-diff-${kind.value}-${ocid.value}-${documentId.value}-${a.value}-${b.value}`, () => target.value ? api.get<Row>('/record_diff', { query: { kind: kind.value, ocid: ocid.value || undefined, document_id: documentId.value || undefined, a: a.value || undefined, b: b.value || undefined } }) : Promise.resolve(null), { default: () => null, watch: [kind, ocid, documentId, a, b] })
function compare(): void { void filters.setAll({ kind: kind.value, ocid: kind.value === 'ocds' ? String(filters.get('draft_id') || '') : undefined, document_id: kind.value === 'document' ? String(filters.get('draft_id') || '') : undefined }) }
function changed(row: Row): boolean { return Boolean(row.changed) }
useHead({ title: 'SectorTrace — Compare revisions' })
</script>

<template>
  <section class="space-y-8"><div class="atlas-hero"><div><p class="atlas-kicker">Revision comparison · source versus derived changes</p><h1>Compare revisions</h1><p class="atlas-lede">Compare two revisions of one procurement notice or parsed document. Publisher amendments remain separate from parser and normalisation changes.</p></div></div><section class="atlas-section atlas-panel atlas-panel-body space-y-4"><div class="grid gap-4 md:grid-cols-[180px_1fr_auto]"><label class="text-sm"><span class="block mb-1 opacity-70">Record kind</span><select v-model="kind" class="w-full rounded border px-3 py-2"><option value="ocds">Procurement notice</option><option value="document">Parsed document</option></select></label><label class="text-sm"><span class="block mb-1 opacity-70">{{ kind === 'ocds' ? 'OCID' : 'Document ID' }}</span><input class="w-full rounded border px-3 py-2" :value="String(filters.get('draft_id') || '')" :placeholder="kind === 'ocds' ? 'ocds-…' : 'document_id'" :aria-label="kind === 'ocds' ? 'OCID' : 'document ID'" @input="filters.set('draft_id', ($event.target as HTMLInputElement).value)"></label><button class="atlas-button primary self-end" type="button" @click="compare">Compare</button></div><p class="text-sm opacity-70">You can also share explicit revision ids as <code>a</code> and <code>b</code> query parameters.</p></section><div v-if="!target" class="atlas-panel atlas-panel-body"><StCaveat text="Give an OCID or document_id, or provide two explicit revision ids as a and b in the URL." /></div><div v-else-if="pending" class="text-sm opacity-60">Comparing revisions…</div><StEmptyState v-else-if="error" variant="unavailable" /><template v-else-if="data"><section class="atlas-section atlas-panel atlas-panel-body space-y-5"><div class="atlas-section-head"><h2>Difference</h2><p>{{ data.note ?? 'Source amendments and derived changes are classified separately.' }}</p></div><StCaveat :text="data.note" /><template v-if="data.kind === 'ocds'"><div class="atlas-grid atlas-grid-4"><div class="atlas-stat"><strong>{{ data.counts?.changed_source ?? '—' }}</strong><span>source fields changed</span></div><div class="atlas-stat"><strong>{{ data.counts?.changed_derived ?? '—' }}</strong><span>derived fields changed</span></div><div class="atlas-stat"><strong>{{ data.same_ocid ? 'Same OCID' : 'Different OCIDs' }}</strong><span>identity check</span></div></div><div class="overflow-x-auto"><table class="w-full text-sm"><thead><tr><th class="text-left p-2">Field</th><th class="text-left p-2">Class</th><th class="text-left p-2">A</th><th class="text-left p-2">B</th></tr></thead><tbody><tr v-for="field in data.fields ?? []" :key="field.field" :class="changed(field) ? 'bg-amber-50 dark:bg-amber-950/20' : ''"><td class="p-2 font-mono">{{ field.field }}</td><td class="p-2">{{ field.class }}</td><td class="p-2">{{ field.a ?? '—' }}</td><td class="p-2">{{ field.b ?? '—' }}</td></tr></tbody></table></div></template><template v-else><div class="atlas-grid atlas-grid-4"><div class="atlas-stat"><strong>{{ data.counts?.changed ?? '—' }}</strong><span>changed elements</span></div><div class="atlas-stat"><strong>{{ data.counts?.added ?? '—' }}</strong><span>added elements</span></div><div class="atlas-stat"><strong>{{ data.counts?.removed ?? '—' }}</strong><span>removed elements</span></div></div><div v-for="item in data.text_changes ?? []" :key="`${item.sequence}-${item.kind}`" class="border-l-2 pl-3"><div class="text-xs opacity-60">#{{ item.sequence }} · {{ item.element_type }} · {{ item.kind }}</div><p v-if="item.a != null" class="text-sm"><strong>A</strong> {{ item.a }}</p><p v-if="item.b != null" class="text-sm"><strong>B</strong> {{ item.b }}</p></div><p v-if="!(data.text_changes ?? []).length" class="text-sm opacity-70">The body text is identical between these versions.</p></template></section></template></section>
</template>
